result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "rubric.py", "content": """"Rubric scoring engine for essay grading with validation."""


class RubricError(ValueError):
    """Raised when a rubric or a selection violates the rubric rules."""


WEIGHT_TOLERANCE = 1e-9

BAND_CUTOFFS = [
    ("exemplary", 90),
    ("proficient", 75),
    ("developing", 60),
    ("beginning", None),
]


def validate_rubric(rubric):
    """Validate a rubric, raising RubricError listing ALL violations."""
    errors = []

    if not isinstance(rubric, dict) or not isinstance(rubric.get("criteria"), list):
        raise RubricError("rubric must be a dict with a 'criteria' list")
    criteria = rubric["criteria"]
    if not criteria:
        errors.append("rubric has no criteria")

    seen_names = set()
    max_points_values = set()

    for i, criterion in enumerate(criteria):
        label = f"criterion[{i}]"
        if not isinstance(criterion, dict):
            errors.append(f"{label}: must be a dict")
            continue

        name = criterion.get("name")
        if not isinstance(name, str) or not name:
            errors.append(f"{label}: missing or invalid 'name'")
            name = None
        elif name in seen_names:
            errors.append(f"duplicate criterion name: '{name}'")
        else:
            seen_names.add(name)

        weight = criterion.get("weight")
        if not isinstance(weight, (int, float)) or isinstance(weight, bool):
            errors.append(f"{label} ('{name}'): missing or non-numeric 'weight'")
        elif weight < 0:
            errors.append(
                f"{label} ('{name}'): weight {weight} is negative"
            )

        levels = criterion.get("levels")
        if not isinstance(levels, list) or len(levels) < 2:
            errors.append(
                f"{label} ('{name}'): must have at least two 'levels'"
            )
            continue

        prev_points = None
        level_max = None
        for j, level in enumerate(levels):
            if not isinstance(level, dict) or "points" not in level:
                errors.append(f"{label} ('{name}') level[{j}]: missing 'points'")
                continue
            points = level["points"]
            if not isinstance(points, (int, float)) or isinstance(points, bool):
                errors.append(
                    f"{label} ('{name}') level[{j}]: non-numeric points {points!r}"
                )
                continue
            if prev_points is not None and not (points > prev_points):
                errors.append(
                    f"{label} ('{name}') level[{j}] ('{level.get('label')}'): "
                    f"points {points} not strictly increasing "
                    f"(previous was {prev_points})"
                )
            prev_points = points
            if "label" not in level:
                errors.append(f"{label} ('{name}') level[{j}]: missing 'label'")
            level_max = points if level_max is None else max(level_max, points)

        if level_max is not None:
            max_points_values.add((name, level_max))

    # Weights must sum to 1.0 within 1e-9.
    weights = [c.get("weight") for c in criteria if isinstance(c, dict)]
    if all(isinstance(w, (int, float)) and not isinstance(w, bool) for w in weights):
        total = sum(weights)
        if abs(total - 1.0) > WEIGHT_TOLERANCE:
            errors.append(
                f"weights sum to {total!r}, expected 1.0 within {WEIGHT_TOLERANCE}"
            )

    # Max points of every criterion must be equal.
    by_value = {}
    for name, mx in sorted(max_points_values, key=lambda t: str(t[0])):
        by_value.setdefault(mx, []).append(name)
    if len(by_value) > 1:
        detail = "; ".join(
            f"max={mx}: {', '.join(names)}" for mx, names in sorted(by_value.items())
        )
        errors.append(f"criteria have unequal max points ({detail})")

    if errors:
        raise RubricError("; ".join(errors))


def score(rubric, selections):
    """Score selections {criterion_name: chosen_points}, return (0-100 score, band)."""
    validate_rubric(rubric)

    errors = []
    criteria_by_name = {}
    for criterion in rubric["criteria"]:
        criteria_by_name[criterion["name"]] = criterion

        if criterion["name"] not in selections:
            errors.append(f"missing selection for criterion '{criterion['name']}'")

    extra = set(selections) - set(criteria_by_name)
    if extra:
        errors.append(
            "selections contain unknown criteria: "
            + ", ".join(f"'{n}'" for n in sorted(extra))
        )

    weighted = 0.0
    for name, chosen in selections.items():
        criterion = criteria_by_name.get(name)
        if criterion is None:
            continue
        level = next(
            (lv for lv in criterion["levels"] if lv["points"] == chosen), None
        )
        if level is None:
            valid = "/".join(str(lv["points"]) for lv in criterion["levels"])
            errors.append(
                f"criterion '{name}': chosen points {chosen!r} is not one of "
                f"the criterion's levels ({valid})"
            )
            continue
        max_points = criterion["levels"][-1]["points"]
        weighted += criterion["weight"] * (chosen / max_points)

    if errors:
        raise RubricError("; ".join(errors))

    result = weighted * 100.0
    band = next(name for name, cutoff in BAND_CUTOFFS if cutoff is None or result >= cutoff)
    return result, band
"})
