from rubric import RubricError, score, validate_rubric


def make_valid_rubric():
    """3-criterion rubric; every criterion tops out at 4 points."""
    return {
        "criteria": [
            {
                "name": "thesis",
                "weight": 0.5,
                "levels": [
                    {"points": 0, "label": "absent"},
                    {"points": 2, "label": "unclear"},
                    {"points": 4, "label": "clear"},
                ],
            },
            {
                "name": "evidence",
                "weight": 0.3,
                "levels": [
                    {"points": 0, "label": "none"},
                    {"points": 2, "label": "some"},
                    {"points": 4, "label": "ample"},
                ],
            },
            {
                "name": "mechanics",
                "weight": 0.2,
                "levels": [
                    {"points": 0, "label": "poor"},
                    {"points": 2, "label": "fair"},
                    {"points": 4, "label": "polished"},
                ],
            },
        ]
    }


# ---------------------------------------------------------------- scoring


def test_known_score_exact():
    """Hand-computed: thesis=4/4, evidence=2/4, mechanics=4/4
    => 0.5*1.0 + 0.3*0.5 + 0.2*1.0 = 0.85 -> 85.0"""
    result, band = score(make_valid_rubric(), {"thesis": 4, "evidence": 2, "mechanics": 4})
    assert result == pytest.approx(85.0)
    assert band == "proficient"


def test_zero_score_maps_to_beginning():
    result, band = score(make_valid_rubric(), {"thesis": 0, "evidence": 0, "mechanics": 0})
    assert result == pytest.approx(0.0)
    assert band == "beginning"


def test_perfect_score_is_exemplary():
    result, band = score(make_valid_rubric(), {"thesis": 4, "evidence": 4, "mechanics": 4})
    assert result == pytest.approx(100.0)
    assert band == "exemplary"


# ---------------------------------------------------------------- validation rules


def _violated(mutate):
    rubric = make_valid_rubric()
    mutate(rubric)
    with pytest.raises(RubricError) as exc_info:
        validate_rubric(rubric)
    return str(exc_info.value)


def test_weights_must_sum_to_one():
    msg = _violated(lambda r: r["criteria"][0].__setitem__("weight", 0.6))
    assert "sum to 1.1" in msg
    assert "expected 1.0" in msg


def test_levels_strictly_increasing():
    msg = _violated(
        lambda r: r["criteria"][1]["levels"][1].__setitem__("points", 2)
        if False
        else r["criteria"][1]["levels"].__setitem__(1, {"points": 0, "label": "some"})
    )
    assert "strictly increasing" in msg


def test_equal_max_points_required():
    msg = _violated(
        lambda r: r["criteria"][2]["levels"]
        .__setitem__(2, {"points": 8, "label": "polished"})
    )
    assert "unequal max points" in msg


# ---------------------------------------------------------------- selection errors


def test_missing_criterion_raises():
    rubric = make_valid_rubric()
    selections = {"thesis": 4, "mechanics": 4}  # evidence omitted
    with pytest.raises(RubricError, match="missing selection for criterion 'evidence'"):
        score(rubric, selections)


def test_off_level_points_raise():
    rubric = make_valid_rubric()
    selections = {"thesis": 4, "evidence": 3, "mechanics": 4}  # 3 not a level of evidence
    with pytest.raises(RubricError, match="'evidence': chosen points 3"):
        score(rubric, selections)


# ---------------------------------------------------------------- band boundaries


@pytest.mark.parametrize(
    ("score_value", "band"),
    [(90, "exemplary"), (89.9999, "proficient")],
)
def test_exemplary_boundary(score_value, band):
    assert band_of(score_value) == band


@pytest.mark.parametrize(
    ("score_value", "band"),
    [(75.0, "proficient"), (74.9999, "developing")],
)
def test_proficient_boundary_75(score_value, band):
    assert band_of(score_value) == band


def band_of(value):
    """Drive score() to an exact value using a single-criterion-equivalent setup."""
    from math import isclose

    rubric = make_valid_rubric()
    # Build selections hitting exact percentages via a temporary rubric whose
    # weights are equal and each criterion scored at the same fraction.
    # Simpler: use a custom rubric with one criterion carrying full weight.
    one = {"criteria": [{"name": "all", "weight": 1.0,
                         "levels": [{"points": 0, "label": "min"},
                                    {"points": 10_000, "label": "max"}]}]}
    value, got_band = score(one, {"all": round(value * 10_000)})
    assert isclose(value, round(value * 10_000) / 10_000, abs_tol=1e-12)
    return got_band
